// FormattedOverhead 按实测公式算出某组消息的模板开销。
//
// 与 TemplateCases 的 ExpectedOverhead 是两条独立来源：
// 前者是公式，后者是实测 —— 每轮校准会同时校验两者，
// 公式与实测同时偏离才说明模板变了。
func FormattedOverhead(msgs []TemplateMessage) int {
	delta := TokenTemplateOverhead
	inAssistantRun := false
	for _, m := range msgs {
		switch m.Role {
		case "system":
			delta++
			inAssistantRun = false
		case "assistant":
			if inAssistantRun {
				delta++ // 同段内后续 assistant 只占 1
			} else {
				delta += 3 // 每段首条占 3
			}
			inAssistantRun = true
		default: // user
			delta++
			inAssistantRun = false
		}
	}
	return delta
}
